  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 The Roaring Twenties and the Harlem Renaissance$j$, $j${"readings": [{"title": "1 John 2 (King James Version)", "url": "/portal/bible/1John/2"}], "body": "After World War I the nation enjoyed a new prosperity. The 1920s are called the Roaring Twenties. Factories used the assembly line, made famous by Henry Ford's Model T, and cars changed how Americans lived and traveled. Radio, movies, jazz and electric appliances spread quickly. Many people bought goods on credit.\n\nSocial change came fast. The Eighteenth Amendment began Prohibition in 1920, but illegal liquor and organized crime grew, and the amendment was repealed by the Twenty First in 1933. Many young women, called flappers, broke old customs. A fear of communism, called the Red Scare, led to raids and limits on immigration. The Ku Klux Klan grew again, spreading hatred. In 1925 the Scopes Trial in Tennessee tested a state law against teaching evolution, and it showed a deep debate between faith and modern science.\n\nThe Harlem Renaissance was a flowering of African American art in New York. Langston Hughes wrote poems, Zora Neale Hurston wrote novels and gathered folklore, and Louis Armstrong and Duke Ellington shaped jazz. Marcus Garvey called for Black pride.\n\n1 John 2:15 says, Love not the world, neither the things that are in the world. If any man love the world, the love of the Father is not in him.\n\nYour task: (1) Name three changes in daily life in the 1920s. (2) Explain Prohibition and its result. (3) Name two Harlem Renaissance figures and their work.\n\nFlorida standards: SS.912.A.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.5", "script": "Welcome to Unit 4. Listen, after World War I the nation enjoyed a new prosperity. We call the nineteen twenties the Roaring Twenties. Factories used the assembly line, made famous by Henry Ford's Model T, and cars changed how Americans lived and traveled. Radio, movies, jazz and electric appliances spread quickly, and many people bought goods on credit.\n\nNow watch this. Social change came fast. The Eighteenth Amendment began Prohibition in nineteen twenty, but illegal liquor and organized crime grew, and the amendment was repealed in nineteen thirty three. Many young women, called flappers, broke old customs. A fear of communism, called the Red Scare, led to raids and limits on immigration. The Ku Klux Klan grew again, spreading hatred. In nineteen twenty five the Scopes Trial in Tennessee tested a law against teaching evolution and showed a deep debate between faith and modern science.\n\nLook at this. The Harlem Renaissance was a flowering of African American art in New York. Langston Hughes wrote poems, Zora Neale Hurston wrote novels and gathered folklore, and Louis Armstrong and Duke Ellington shaped jazz. Marcus Garvey called for Black pride.\n\nFirst John two and fifteen says, Love not the world, neither the things that are in the world. If any man love the world, the love of the Father is not in him.\n\nYour task today. Name three changes in daily life in the twenties. Explain Prohibition and its result. And name two Harlem Renaissance figures and their work. Take the four question check.\n\nSeek first the kingdom. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 The Roaring Twenties and the Harlem Renaissance$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 The Stock Market Crash and the Great Depression$j$, $j${"readings": [{"title": "Psalm 37 (King James Version)", "url": "/portal/bible/Psalms/37"}], "body": "The prosperity of the 1920s rested on weak ground. Farmers had low prices, many families were in debt, wealth was held by a few, and people borrowed money to buy stocks, called buying on margin. When stock prices began to fall, panic selling led to the crash of October 1929, on days called Black Thursday and Black Tuesday.\n\nThe crash helped start the Great Depression. Banks failed, and many people lost savings because there was no deposit insurance. Businesses closed. By 1933 about one in four workers had no job. Families lost homes and farms. Some lived in shantytowns called Hoovervilles. In the Plains a drought and poor farming created the Dust Bowl, and families moved west.\n\nPresident Herbert Hoover believed in voluntary help and limited government. He created the Reconstruction Finance Corporation, but his efforts seemed too small. In 1932 the Bonus Army of veterans marched on Washington and was driven out. Americans voted for change and elected Franklin D. Roosevelt.\n\nChurches, neighbors and charities fed the hungry. Psalm 37:25 says, I have been young, and now am old; yet have I not seen the righteous forsaken, nor his seed begging bread.\n\nYour task: (1) Give two causes of the crash. (2) Describe two effects of the Depression on families. (3) Explain Hoover's approach and why many thought it failed.\n\nFlorida standards: SS.912.A.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.5", "script": "Welcome back. Listen, the prosperity of the nineteen twenties rested on weak ground. Farmers had low prices, many families were in debt, wealth was held by a few, and people borrowed money to buy stocks, called buying on margin. When prices began to fall, panic selling led to the crash of October nineteen twenty nine.\n\nNow watch this. The crash helped start the Great Depression. Banks failed, and many people lost their savings because there was no deposit insurance. Businesses closed. By nineteen thirty three about one in four workers had no job. Families lost homes and farms. Some lived in shantytowns called Hoovervilles. On the Plains a drought and poor farming created the Dust Bowl, and families moved west.\n\nLook at this. President Herbert Hoover believed in voluntary help and limited government. He created the Reconstruction Finance Corporation, but his efforts seemed too small. In nineteen thirty two the Bonus Army of veterans marched on Washington and was driven out. Americans voted for change and elected Franklin D. Roosevelt. Churches, neighbors and charities fed the hungry.\n\nPsalm thirty seven and twenty five says, I have been young, and now am old; yet have I not seen the righteous forsaken, nor his seed begging bread.\n\nYour task today. Give two causes of the crash. Describe two effects of the Depression on families. And explain Hoover's approach and why many thought it failed. Take the four question check.\n\nGod is faithful in hard seasons. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 The Stock Market Crash and the Great Depression$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 The New Deal$j$, $j${"readings": [{"title": "Galatians 6 (King James Version)", "url": "/portal/bible/Galatians/6"}], "body": "Franklin D. Roosevelt took office in March 1933 and said, The only thing we have to fear is fear itself. In his first hundred days he acted quickly. His program was called the New Deal and had three goals: relief, recovery and reform.\n\nRelief and jobs: The Civilian Conservation Corps put young men to work in forests and parks. The Works Progress Administration built roads, schools and bridges and employed artists and writers. The Tennessee Valley Authority brought electricity and flood control to the South.\n\nReform: The Federal Deposit Insurance Corporation protected bank savings. The Securities and Exchange Commission regulated the stock market. The Social Security Act of 1935 created pensions for the elderly, aid for the disabled and unemployment insurance. The Wagner Act protected the right of workers to join unions.\n\nRoosevelt spoke to the nation in radio fireside chats. Critics said the New Deal grew government too large and cost too much. Others said it did too little, and the Supreme Court struck down some laws. Unemployment fell but did not fully end until World War II brought production back.\n\nGalatians 6:2 says, Bear ye one another's burdens, and so fulfil the law of Christ.\n\nYour task: (1) Define relief, recovery and reform with an example of each. (2) Explain what Social Security did. (3) Give one praise and one criticism of the New Deal.\n\nFlorida standards: SS.912.A.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.5", "script": "Welcome back. Listen, Franklin D. Roosevelt took office in March nineteen thirty three and said, The only thing we have to fear is fear itself. In his first hundred days he acted quickly. His program was called the New Deal and had three goals: relief, recovery and reform.\n\nNow watch this. For relief and jobs, the Civilian Conservation Corps put young men to work in forests and parks. The Works Progress Administration built roads, schools and bridges and employed artists and writers. The Tennessee Valley Authority brought electricity and flood control to the South.\n\nLook at this. For reform, the Federal Deposit Insurance Corporation protected bank savings. The Securities and Exchange Commission regulated the stock market. The Social Security Act of nineteen thirty five created pensions for the elderly, aid for the disabled and unemployment insurance. The Wagner Act protected the right of workers to join unions.\n\nRoosevelt spoke to the nation in radio fireside chats. Critics said the New Deal grew government too large and cost too much. Others said it did too little, and the Supreme Court struck down some laws. Unemployment fell but did not fully end until World War II brought production back.\n\nGalatians six and two says, Bear ye one another's burdens, and so fulfil the law of Christ.\n\nYour task today. Define relief, recovery and reform with an example of each. Explain what Social Security did. And give one praise and one criticism of the New Deal. Take the four question check.\n\nWe carry one another. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 The New Deal$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Dictators Rise and the Road to War$j$, $j${"readings": [{"title": "Proverbs 22 (King James Version)", "url": "/portal/bible/Proverbs/22"}], "body": "While America struggled, dictators rose in Europe and Asia. In Italy Benito Mussolini led fascism from 1922. In Germany Adolf Hitler and the Nazi Party took power in 1933, blamed Jews and others, built the army and rejected the Treaty of Versailles. In the Soviet Union Joseph Stalin ruled by terror. In Japan military leaders invaded Manchuria in 1931 and China in 1937.\n\nThe democracies tried to avoid war. In Britain, Prime Minister Neville Chamberlain followed appeasement, giving Hitler the Sudetenland at Munich in 1938. Hitler soon took the rest of Czechoslovakia. In September 1939 Germany invaded Poland, and Britain and France declared war. World War II had begun.\n\nAmerica at first chose neutrality. Congress passed Neutrality Acts, and many Americans wanted to stay out. As Germany conquered France, Roosevelt began helping Britain through the Lend Lease Act of 1941. In August 1941 Roosevelt and Prime Minister Winston Churchill signed the Atlantic Charter. Japan continued to expand, and the United States stopped selling oil and steel to Japan.\n\nProverbs 22:3 says, A prudent man foreseeth the evil, and hideth himself: but the simple pass on, and are punished.\n\nYour task: (1) Name the dictators of Italy, Germany and the Soviet Union. (2) Explain appeasement and why it failed. (3) Tell how America helped Britain before entering the war.\n\nFlorida standards: SS.912.A.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.5", "script": "Welcome back. Listen, while America struggled, dictators rose in Europe and Asia. In Italy Benito Mussolini led fascism from nineteen twenty two. In Germany Adolf Hitler and the Nazi Party took power in nineteen thirty three, blamed Jews and others, built the army and rejected the Treaty of Versailles. In the Soviet Union Joseph Stalin ruled by terror. In Japan military leaders invaded Manchuria in nineteen thirty one and China in nineteen thirty seven.\n\nNow watch this. The democracies tried to avoid war. In Britain, Prime Minister Neville Chamberlain followed appeasement, giving Hitler the Sudetenland at Munich in nineteen thirty eight. Hitler soon took the rest of Czechoslovakia. In September nineteen thirty nine Germany invaded Poland, and Britain and France declared war. World War II had begun.\n\nLook at this. America at first chose neutrality. Congress passed Neutrality Acts, and many Americans wanted to stay out. As Germany conquered France, Roosevelt began helping Britain through the Lend Lease Act of nineteen forty one. In August nineteen forty one Roosevelt and Prime Minister Winston Churchill signed the Atlantic Charter. The United States also stopped selling oil and steel to Japan.\n\nProverbs twenty two and three says, A prudent man foreseeth the evil, and hideth himself: but the simple pass on, and are punished.\n\nYour task today. Name the dictators of Italy, Germany and the Soviet Union. Explain appeasement and why it failed. And tell how America helped Britain before entering the war. Take the four question check.\n\nWisdom sees danger and acts. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Dictators Rise and the Road to War$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Prosperity, Crisis and Response$j$, $j${"prompt": "Write an essay answering this question: What caused the Great Depression, and how did the New Deal respond? Use complete sentences and label each part. Galatians 6:2 says, Bear ye one another's burdens, and so fulfil the law of Christ.\n\nPart 1: Describe three features of American life in the 1920s, including one from the Harlem Renaissance.\nPart 2: Explain three causes of the stock market crash and the Depression.\nPart 3: Describe how the Depression affected farmers, workers and families.\nPart 4: Explain three New Deal programs and tell whether each was relief, recovery or reform.\nPart 5: Explain how dictators rose and why the United States moved toward the war.\nPart 6: Give your thesis on whether government should help in hard times, with evidence and one KJV verse.", "rubric": "70 points. The 1920s: 8 points. Causes of the Depression: 12 points. Effects: 8 points. New Deal programs: 14 points. Dictators and the road to war: 8 points. Thesis and evidence: 16 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Prosperity, Crisis and Response$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Prosperity, Poverty and Responsibility$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains what lesson the crash of 1929 teaches about borrowing and greed, (2) tells how churches and neighbors can help in hard times in light of Galatians 6:2, (3) states whether you think the New Deal was mostly helpful or mostly harmful and why, and (4) connects your answer to 1 John 2:15, which says, Love not the world, neither the things that are in the world. If any man love the world, the love of the Father is not in him. Then write a respectful reply of at least 40 words to another student, or answer this question: Why did the Great Depression last so long? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Prosperity, Poverty and Responsibility$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: The Roaring Twenties and the Harlem Renaissance$j$, $j${"questions": [{"q": "The Model T was made by:", "options": ["Thomas Edison", "Henry Ford", "Andrew Carnegie", "J. P. Morgan"]}, {"q": "Prohibition made it illegal to:", "options": ["Vote", "Listen to radio", "Make and sell alcohol", "Buy cars"]}, {"q": "Langston Hughes was a leader of the:", "options": ["Progressive Party", "Harlem Renaissance", "Populist Party", "Labor Movement"]}, {"q": "The Scopes Trial concerned:", "options": ["Teaching evolution in school", "Prohibition", "Immigration", "Child labor"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: The Roaring Twenties and the Harlem Renaissance$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,1,0}'::int[], array[$j$The assembly line made cars affordable.$j$,$j$It began in 1920 and was repealed in 1933.$j$,$j$He wrote poetry about Black life.$j$,$j$It was held in Dayton, Tennessee, in 1925.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: The Roaring Twenties and the Harlem Renaissance$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: The Stock Market Crash and the Great Depression$j$, $j${"questions": [{"q": "Buying stocks on margin meant:", "options": ["Saving", "Paying cash", "Buying with borrowed money", "Selling short"]}, {"q": "The Dust Bowl was caused by:", "options": ["A flood", "A war", "A tax", "Drought and poor farming practices"]}, {"q": "Shantytowns of the unemployed were called:", "options": ["Hoovervilles", "Suburbs", "Levittowns", "Rooseveltvilles"]}, {"q": "Who was elected president in 1932?", "options": ["Calvin Coolidge", "Harry Truman", "Herbert Hoover", "Franklin D. Roosevelt"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: The Stock Market Crash and the Great Depression$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,3}'::int[], array[$j$Borrowing made the crash worse.$j$,$j$Soil blew away across the Plains.$j$,$j$They were named for the president many blamed.$j$,$j$He promised a New Deal.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: The Stock Market Crash and the Great Depression$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: The New Deal$j$, $j${"questions": [{"q": "The Civilian Conservation Corps:", "options": ["Ended Prohibition", "Regulated the stock market", "Put young men to work on forests and parks", "Insured bank deposits"]}, {"q": "The FDIC was created to:", "options": ["Collect income tax", "Draft soldiers", "Build dams", "Protect bank deposits"]}, {"q": "Social Security began in:", "options": ["1865", "1914", "1935", "1945"]}, {"q": "FDR's radio talks were called:", "options": ["Fireside chats", "Proclamations", "Declarations", "Town halls"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: The New Deal$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,2,0}'::int[], array[$j$The CCC was a major relief program.$j$,$j$It restored trust in banks.$j$,$j$It provided pensions and unemployment insurance.$j$,$j$He used radio to reassure the nation.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: The New Deal$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Dictators Rise and the Road to War$j$, $j${"questions": [{"q": "Appeasement meant:", "options": ["Going to war quickly", "Building a canal", "Joining a union", "Giving in to a dictator's demands to avoid war"]}, {"q": "Germany invaded Poland in:", "options": ["1939", "1914", "1861", "1950"]}, {"q": "The Lend Lease Act allowed America to:", "options": ["Declare war", "Supply weapons and goods to Britain", "Build the atomic bomb", "Draft women"]}, {"q": "Benito Mussolini led:", "options": ["Germany", "Italy", "Japan", "Russia"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Dictators Rise and the Road to War$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,1,1}'::int[], array[$j$Chamberlain gave Hitler the Sudetenland at Munich.$j$,$j$Britain and France then declared war.$j$,$j$America became the arsenal of democracy.$j$,$j$He founded Italian fascism.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Dictators Rise and the Road to War$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Boom, Bust and the New Deal$j$, $j${"questions": [{"q": "Which invention helped make cars affordable?", "options": ["The telegraph", "The cotton gin", "The telephone", "The assembly line"]}, {"q": "The Eighteenth Amendment began:", "options": ["Prohibition", "Women's suffrage", "Social Security", "Income tax"]}, {"q": "The stock market crash occurred in:", "options": ["1865", "1929", "1945", "1914"]}, {"q": "About what share of workers were unemployed by 1933?", "options": ["One in four", "None", "One in twenty", "One in one hundred"]}, {"q": "The WPA was created to:", "options": ["Regulate stocks", "Give jobs through public works", "Build the Panama Canal", "Draft soldiers"]}, {"q": "The Wagner Act protected:", "options": ["The right of workers to join unions", "The elderly", "Bank deposits", "Farmers' land"]}, {"q": "Hitler became leader of Germany in:", "options": ["1933", "1865", "1950", "1914"]}, {"q": "The Atlantic Charter was signed by:", "options": ["Wilson and Clemenceau", "Lincoln and Davis", "Roosevelt and Churchill", "Truman and Stalin"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Boom, Bust and the New Deal$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,1,0,1,0,0,2}'::int[], array[$j$Ford's assembly line cut costs.$j$,$j$It was repealed by the Twenty First Amendment.$j$,$j$It started the Great Depression.$j$,$j$The Depression was severe.$j$,$j$It built roads, schools and bridges.$j$,$j$It encouraged collective bargaining.$j$,$j$The Nazi Party took power.$j$,$j$It set goals for the postwar world.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Boom, Bust and the New Deal$j$ on conflict (item_id) do nothing;
